function twoSum(nums, target) {
    // Create array of [value, originalIndex] pairs
    const indexedNums = nums.map((num, i) => [num, i]);
    // Sort by values
    indexedNums.sort((a, b) => a[0] - b[0]);

    let left = 0, right = indexedNums.length - 1;

    while (left < right) {
        const currentSum = indexedNums[left][0] + indexedNums[right][0];

        if (currentSum === target) {
            // Return original indices, smaller index first
            const idx1 = indexedNums[left][1];
            const idx2 = indexedNums[right][1];
            return [Math.min(idx1, idx2), Math.max(idx1, idx2)];
        } else if (currentSum < target) {
            left++;
        } else {
            right--;
        }
    }

    return [];
}

