class Solution {
    public int[] twoSum(int[] nums, int target) {
        // Create array of [value, originalIndex] pairs
        int[][] indexedNums = new int[nums.length][2];
        for (int i = 0; i < nums.length; i++) {
            indexedNums[i][0] = nums[i];
            indexedNums[i][1] = i;
        }
        // Sort by values
        Arrays.sort(indexedNums, (a, b) -> Integer.compare(a[0], b[0]));

        int left = 0, right = indexedNums.length - 1;

        while (left < right) {
            int currentSum = indexedNums[left][0] + indexedNums[right][0];

            if (currentSum == target) {
                // Return original indices, smaller index first
                int idx1 = indexedNums[left][1];
                int idx2 = indexedNums[right][1];
                return new int[] {Math.min(idx1, idx2), Math.max(idx1, idx2)};
            } else if (currentSum < target) {
                left++;
            } else {
                right--;
            }
        }

        return new int[] {};
    }
}

