vector<int> twoSum(vector<int>& nums, int target) {
    // Create vector of {value, originalIndex} pairs
    vector<pair<int, int>> indexedNums;
    for (int i = 0; i < nums.size(); i++) {
        indexedNums.push_back({nums[i], i});
    }
    // Sort by values
    sort(indexedNums.begin(), indexedNums.end());

    int left = 0, right = indexedNums.size() - 1;

    while (left < right) {
        int currentSum = indexedNums[left].first + indexedNums[right].first;

        if (currentSum == target) {
            // Return original indices, smaller index first
            int idx1 = indexedNums[left].second;
            int idx2 = indexedNums[right].second;
            return {min(idx1, idx2), max(idx1, idx2)};
        } else if (currentSum < target) {
            left++;
        } else {
            right--;
        }
    }

    return {};
}

